sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {

  var c = this;


  /* ============================================================
     INITIAL STATE
     ============================================================ */

  c.sidebarOpen = true;

  c.searchText = '';

  c.selectedStudent = null;

  c.filteredRecords = [];


  /* ============================================================
     SIDEBAR
     ============================================================ */

  c.toggleSidebar = function() {

    c.sidebarOpen = !c.sidebarOpen;

  };


  c.openSidebar = function() {

    c.sidebarOpen = true;

  };


  c.closeSidebar = function() {

    c.sidebarOpen = false;

  };


  /* ============================================================
     NAVIGATION
     ============================================================ */

  c.openPage = function(pageId) {

    if (!pageId) {
      return;
    }

    var trainerId = '';

    if (
      c.data &&
      c.data.trainer &&
      c.data.trainer.id
    ) {

      trainerId =
        c.data.trainer.id;

    }


    var url =
      '?id=' +
      encodeURIComponent(pageId);


    if (trainerId) {

      url +=
        '&trainer=' +
        encodeURIComponent(trainerId);

    }


    $window.location.href = url;

  };


  /* ============================================================
     PREPARE RECORDS
     ============================================================ */

  c.prepareRecords = function() {

    if (
      !c.data ||
      !angular.isArray(
        c.data.records
      )
    ) {

      c.filteredRecords = [];

      return;

    }


    c.filteredRecords =
      angular.copy(
        c.data.records
      );

  };


  /* ============================================================
     SEARCH
     ============================================================ */

  c.filterStudents = function() {

    if (
      !c.data ||
      !angular.isArray(
        c.data.records
      )
    ) {

      c.filteredRecords = [];

      return;

    }


    var search =
      (
        c.searchText ||
        ''
      )
      .toString()
      .toLowerCase()
      .trim();


    if (!search) {

      c.filteredRecords =
        angular.copy(
          c.data.records
        );

      return;

    }


    c.filteredRecords =
      c.data.records.filter(
        function(record) {

          var studentId =
            (
              record.student_id ||
              ''
            )
            .toString()
            .toLowerCase();


          var studentName =
            (
              record.name ||
              ''
            )
            .toString()
            .toLowerCase();


          var intelligenceId =
            (
              record.intelligence_id ||
              ''
            )
            .toString()
            .toLowerCase();


          return (
            studentId.indexOf(search) !== -1 ||
            studentName.indexOf(search) !== -1 ||
            intelligenceId.indexOf(search) !== -1
          );

        }
      );

  };


  c.clearSearch = function() {

    c.searchText = '';

    c.filterStudents();

  };


  /* ============================================================
     OPEN STUDENT
     ============================================================ */

  c.openStudent = function(student) {

    if (!student) {
      return;
    }


    c.selectedStudent =
      angular.copy(student);


    $timeout(
      function() {

        var detail =
          document.querySelector(
            '.placement-detail-panel'
          );


        if (detail) {

          detail.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
          });

        }

      },
      80
    );

  };


  /* ============================================================
     CLOSE STUDENT
     ============================================================ */

  c.closeStudent = function() {

    c.selectedStudent = null;


    $timeout(
      function() {

        var search =
          document.querySelector(
            '.placement-search-box input'
          );


        if (search) {

          search.focus();

        }

      },
      80
    );

  };


  /* ============================================================
     RISK CLASS
     ============================================================ */

  c.getRiskClass = function(risk) {

    var value =
      (
        risk ||
        ''
      )
      .toString()
      .toLowerCase()
      .trim();


    if (value === 'low') {

      return 'risk-low';

    }


    if (value === 'medium') {

      return 'risk-medium';

    }


    if (value === 'high') {

      return 'risk-high';

    }


    return 'risk-default';

  };


  /* ============================================================
     REFRESH
     ============================================================ */

  c.refresh = function() {

    c.selectedStudent = null;

    c.searchText = '';


    c.server.update().then(
      function() {

        c.prepareRecords();

      }
    );

  };


  /* ============================================================
     KEYBOARD
     ============================================================ */

  c.keyHandler = function(event) {

    if (
      event &&
      event.keyCode === 27 &&
      c.selectedStudent
    ) {

      c.closeStudent();

    }

  };


  document.addEventListener(
    'keydown',
    c.keyHandler
  );


  /* ============================================================
     INITIAL LOAD
     ============================================================ */

  c.prepareRecords();


  /* ============================================================
     CLEANUP
     ============================================================ */

  c.$onDestroy = function() {

    document.removeEventListener(
      'keydown',
      c.keyHandler
    );

  };

};

sp_widget.css:
/* ============================================================
   CAMPUS360 TRAINER
   PLACEMENT INTELLIGENCE

   FULL SCREEN / 100% VIEW
   DASHBOARD STYLE SIDEBAR
   DASHBOARD STYLE TOPBAR
   SERVICE NOW CHROME HIDDEN
   ============================================================ */


/* ============================================================
   VARIABLES
   ============================================================ */

.campus360-trainer-app {

    --sidebar-width: 280px;

    --purple: #6847e8;
    --purple-dark: #4d2fc2;
    --purple-soft: #eee8ff;
    --purple-border: #d5c8f5;

    --teal: #159b95;
    --teal-dark: #08756f;
    --teal-soft: #ddf7f3;
    --teal-border: #b8dfda;

    --blue: #397cc8;
    --blue-dark: #245d9c;
    --blue-soft: #e5f1ff;
    --blue-border: #c7dff5;

    --orange: #df8440;
    --orange-dark: #b96122;
    --orange-soft: #fff0e2;
    --orange-border: #efd0b3;

    --pink: #d45d86;
    --pink-dark: #b44169;
    --pink-soft: #fde9f0;
    --pink-border: #edc4d5;

    --coral: #dc6c58;
    --coral-dark: #b84b39;
    --coral-soft: #ffe9e3;

    --green: #329268;
    --green-dark: #24744f;
    --green-soft: #e5f6ed;

    --yellow-dark: #946b12;

    --navy: #132c47;
    --text: #2d4057;
    --muted: #7c8da0;

}


/* ============================================================
   GLOBAL RESET
   ============================================================ */

html,
body {

    margin: 0 !important;

    padding: 0 !important;

    width: 100% !important;

    min-width: 100% !important;

}


body {

    overflow-x: hidden !important;

}


/* ============================================================
   REMOVE SERVICE NOW OUTER CHROME
   THIS REMOVES THE "SYSTEM ADMINISTRATOR" HEADER
   WHEN THIS CAMPUS360 PAGE IS PRESENT
   ============================================================ */

body:has(.campus360-trainer-app) {

    overflow: hidden !important;

}


/* Common ServiceNow portal/navbar elements */

body:has(.campus360-trainer-app) .navbar,
body:has(.campus360-trainer-app) .navbar-inverse,
body:has(.campus360-trainer-app) .sp-navbar,
body:has(.campus360-trainer-app) .sp-nav,
body:has(.campus360-trainer-app) #sp-nav-bar,
body:has(.campus360-trainer-app) #sp-navbar,
body:has(.campus360-trainer-app) #sp-nav-header,
body:has(.campus360-trainer-app) .sp-navbar-top {

    display: none !important;

}


/* ============================================================
   SERVICENOW OUTER WRAPPERS
   ============================================================ */

body:has(.campus360-trainer-app) .container,
body:has(.campus360-trainer-app) .container-fluid,
body:has(.campus360-trainer-app) .row,
body:has(.campus360-trainer-app) [class*="col-"],
body:has(.campus360-trainer-app) .well,
body:has(.campus360-trainer-app) .panel,
body:has(.campus360-trainer-app) .panel-body {

    width: 100% !important;

    max-width: none !important;

    min-width: 0 !important;

    margin: 0 !important;

    padding-left: 0 !important;

    padding-right: 0 !important;

    border: 0 !important;

    box-shadow: none !important;

    background: transparent !important;

}


/* ============================================================
   APPLICATION
   ============================================================ */

.campus360-trainer-app {

    position: fixed !important;

    left: 0 !important;

    top: 0 !important;

    right: 0 !important;

    bottom: 0 !important;

    width: 100vw !important;

    height: 100vh !important;

    min-width: 100vw !important;

    max-width: 100vw !important;

    min-height: 100vh !important;

    max-height: 100vh !important;

    margin: 0 !important;

    padding: 0 !important;

    display: block !important;

    z-index: 999999 !important;

    overflow: hidden !important;

    background:

        linear-gradient(
            135deg,
            #f4f7fc 0%,
            #f8f9fc 55%,
            #f6f8fc 100%
        );

    color: var(--text);

    font-family:
        Inter,
        "Segoe UI",
        Arial,
        Helvetica,
        sans-serif;

    -webkit-font-smoothing: antialiased;

}


.campus360-trainer-app,
.campus360-trainer-app *,
.campus360-trainer-app *::before,
.campus360-trainer-app *::after {

    box-sizing: border-box;

}


/* ============================================================
   SIDEBAR
   ============================================================ */

.campus360-trainer-sidebar {

    position: fixed !important;

    left: 0 !important;

    top: 0 !important;

    bottom: 0 !important;

    width: var(--sidebar-width) !important;

    height: 100vh !important;

    min-height: 100vh !important;

    max-height: 100vh !important;

    z-index: 1000000 !important;

    display: flex;

    flex-direction: column;

    background:

        linear-gradient(
            180deg,
            #ffffff 0%,
            #ffffff 70%,
            #fbf9ff 100%
        );

    border-right: 1px solid #dfe5ec;

    box-shadow:

        5px
        0
        20px
        rgba(30,43,61,.045);

    overflow: hidden;

    transition:

        width .24s ease,
        transform .24s ease;

}


/* COLLAPSED */

.campus360-trainer-app.sidebar-collapsed
.campus360-trainer-sidebar {

    width: 0 !important;

    min-width: 0 !important;

    border-right: 0 !important;

}


/* ============================================================
   BRAND
   ============================================================ */

.trainer-brand {

    height: 96px;

    min-height: 96px;

    flex-shrink: 0;

    padding:
        0
        18px;

    display: flex;

    align-items: center;

    gap: 13px;

    background:

        linear-gradient(
            135deg,
            #ffffff,
            #faf7ff
        );

    border-bottom:
        1px
        solid
        #edf0f5;

}


.trainer-brand-mark {

    width: 50px;

    height: 50px;

    min-width: 50px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 14px;

    background:

        linear-gradient(
            135deg,
            #693df4,
            #8054ff
        );

    color: #ffffff;

    font-size: 23px;

    box-shadow:

        0
        8px
        19px
        rgba(104,61,242,.22);

}


.trainer-brand-text {

    min-width: 0;

    display: flex;

    flex-direction: column;

}


.trainer-brand-text strong {

    display: block;

    color: #182c3b;

    font-size: 20px;

    line-height: 1;

    font-weight: 900;

    letter-spacing: -.3px;

}


.trainer-brand-text span {

    display: block;

    margin-top: 5px;

    color: #66778c;

    font-size: 9px;

    line-height: 1;

    font-weight: 900;

    letter-spacing: 1.35px;

}


/* ============================================================
   PROFILE
   ============================================================ */

.trainer-profile-mini {

    margin:
        18px
        10px
        14px;

    min-height: 70px;

    padding: 11px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    gap: 10px;

    background:

        linear-gradient(
            135deg,
            #faf7ff,
            #f1ebff
        );

    border:
        1px
        solid
        #ded3f7;

    border-radius: 13px;

    text-decoration: none !important;

    transition: .18s ease;

}


.trainer-profile-mini:hover {

    background:

        linear-gradient(
            135deg,
            #f3edff,
            #eae2ff
        );

    border-color:
        #cfc1ee;

    transform:
        translateY(-1px);

}


.trainer-avatar {

    width: 45px;

    height: 45px;

    min-width: 45px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 12px;

    background:

        linear-gradient(
            135deg,
            #693df4,
            #8054ff
        );

    color: #ffffff;

    font-size: 12px;

    font-weight: 950;

    box-shadow:

        0
        6px
        13px
        rgba(104,61,242,.17);

}


.trainer-profile-info {

    min-width: 0;

    flex: 1;

}


.trainer-profile-info strong {

    display: block;

    overflow: hidden;

    color: #263b4f;

    font-size: 13px;

    line-height: 1.15;

    font-weight: 900;

    white-space: nowrap;

    text-overflow: ellipsis;

}


.trainer-profile-info span {

    display: block;

    margin-top: 4px;

    color: #758598;

    font-size: 9px;

    font-weight: 750;

}


.trainer-profile-arrow {

    color: #8a98a7;

    font-size: 19px;

}


/* ============================================================
   NAV
   ============================================================ */

.trainer-nav {

    flex: 1;

    min-height: 0;

    padding:
        0
        7px
        20px;

    overflow-x: hidden;

    overflow-y: auto;

}


.trainer-nav::-webkit-scrollbar {

    width: 5px;

}


.trainer-nav::-webkit-scrollbar-track {

    background: transparent;

}


.trainer-nav::-webkit-scrollbar-thumb {

    background: #ddd5f1;

    border-radius: 10px;

}


.trainer-nav-label {

    margin:
        18px
        7px
        8px;

    color: #7a899a;

    font-size: 9px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1.3px;

}


.trainer-nav-item {

    position: relative;

    width: 100%;

    min-height: 48px;

    margin:
        2px
        0;

    padding:
        0
        11px;

    display: flex;

    align-items: center;

    gap: 11px;

    border-radius: 10px;

    color: #40556b;

    text-decoration: none !important;

    font-size: 13px;

    line-height: 1.2;

    font-weight: 850;

    transition:
        background .18s ease,
        color .18s ease,
        transform .18s ease;

}


.trainer-nav-item:hover {

    background:

        linear-gradient(
            90deg,
            #f2ecff,
            #faf8ff
        );

    color: #6541d8;

    transform:
        translateX(1px);

}


.trainer-nav-item.active {

    color: #6540d7;

    background:

        linear-gradient(
            90deg,
            #ebe4ff,
            #f5f1ff
        );

    border-left:
        4px
        solid
        #1976d2;

    padding-left: 7px;

    box-shadow:

        inset
        0
        0
        0
        1px
        #ded4f5;

}


.trainer-nav-item.active::before {

    content: "";

    position: absolute;

    left: 0;

    top: 8px;

    bottom: 8px;

    width: 4px;

    border-radius:
        0
        4px
        4px
        0;

    background:

        linear-gradient(
            180deg,
            #7e5af0,
            #5d3ad0
        );

}


.trainer-nav-icon {

    width: 28px;

    min-width: 28px;

    height: 28px;

    display: flex;

    align-items: center;

    justify-content: center;

    color: #63758b;

    font-size: 17px;

}


.trainer-nav-item.active
.trainer-nav-icon {

    color: #6541da;

}


.trainer-nav-text {

    flex: 1;

    min-width: 0;

}


.trainer-nav-count {

    margin-left: auto;

    min-width: 23px;

    height: 23px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 20px;

    background: #e8e0ff;

    color: #6340d1;

    font-size: 9px;

    font-weight: 900;

}


/* ============================================================
   SIDEBAR BACKDROP
   ============================================================ */

.trainer-sidebar-backdrop {

    display: none;

}


/* ============================================================
   MAIN
   ============================================================ */

.campus360-trainer-main {

    position: absolute;

    left: var(--sidebar-width);

    top: 0;

    right: 0;

    bottom: 0;

    width:
        calc(100vw - var(--sidebar-width)) !important;

    max-width:
        calc(100vw - var(--sidebar-width)) !important;

    min-width: 0 !important;

    height: 100vh;

    min-height: 100vh;

    margin: 0 !important;

    padding: 0 !important;

    background:

        linear-gradient(
            180deg,
            #f3f7fc 0%,
            #f8f9fc 55%,
            #f5faf9 100%
        );

    overflow-x: hidden;

    overflow-y: auto;

    transition:

        left .24s ease,
        width .24s ease,
        max-width .24s ease;

}


.campus360-trainer-app.sidebar-collapsed
.campus360-trainer-main {

    left: 0;

    width: 100vw !important;

    max-width: 100vw !important;

}


/* ============================================================
   TOPBAR
   ============================================================ */

.trainer-topbar {

    position: sticky;

    top: 0;

    z-index: 900;

    width: 100%;

    height: 72px;

    min-height: 72px;

    padding:
        0
        20px
        0
        24px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 18px;

    background:

        linear-gradient(
            90deg,
            #ffffff 0%,
            #fbfdff 60%,
            #f7fcfb 100%
        );

    border-bottom:
        1px
        solid
        #dce4ec;

    box-shadow:

        0
        2px
        10px
        rgba(26,43,62,.035);

}


.trainer-topbar-left {

    min-width: 0;

    display: flex;

    align-items: center;

    gap: 12px;

}


.trainer-hamburger {

    width: 43px;

    height: 43px;

    min-width: 43px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px
        solid
        #d5dfe8;

    border-radius: 10px;

    background: #ffffff;

    color: #526a81;

    font-size: 18px;

    cursor: pointer;

    transition: .18s ease;

}


.trainer-hamburger:hover {

    color: #6943dd;

    background: #f5f1ff;

    border-color: #cec0f1;

}


.trainer-page-heading {

    min-width: 0;

    display: flex;

    flex-direction: column;

}


.trainer-topbar-eyebrow {

    display: block;

    color: #7043e4;

    font-size: 9px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1.7px;

}


.trainer-topbar-title {

    display: block;

    margin-top: 4px;

    color: #19324b;

    font-size: 16px;

    line-height: 1.1;

    font-weight: 900;

}


.trainer-topbar-actions {

    display: flex;

    align-items: center;

    gap: 9px;

    flex-shrink: 0;

}


.trainer-top-icon {

    position: relative;

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px
        solid
        #d6e0e8;

    border-radius: 10px;

    background: #ffffff;

    color: #586f84;

    font-size: 16px;

    cursor: pointer;

    transition: .18s ease;

}


.trainer-top-icon:hover {

    color: #6843dc;

    background: #f5f1ff;

    border-color: #cfc1f3;

}


.trainer-notification-button {

    overflow: visible;

}


.trainer-notification-button
.fa-bell {

    color: #efa100;

    font-size: 17px;

}


.trainer-notification-dot {

    position: absolute;

    top: 7px;

    right: 7px;

    width: 8px;

    height: 8px;

    border-radius: 50%;

    background: #ef4444;

    border:
        2px
        solid
        #ffffff;

}


.trainer-top-profile {

    min-height: 43px;

    padding-left: 11px;

    display: flex;

    align-items: center;

    gap: 8px;

    border-left:
        1px
        solid
        #e2e7ed;

    text-decoration: none !important;

}


.trainer-top-avatar {

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    background:

        linear-gradient(
            135deg,
            #6840ee,
            #8054ff
        );

    color: #ffffff;

    font-size: 10px;

    font-weight: 950;

}


.trainer-top-profile-text {

    min-width: 78px;

    display: flex;

    flex-direction: column;

}


.trainer-top-profile-text strong {

    display: block;

    color: #23394f;

    font-size: 11px;

    line-height: 1.1;

    font-weight: 900;

}


.trainer-top-profile-text span {

    display: block;

    margin-top: 3px;

    color: #7a899a;

    font-size: 8px;

    font-weight: 750;

}


/* ============================================================
   PAGE CONTENT
   ============================================================ */

.placement-intelligence-page {

    width: 100% !important;

    max-width: none !important;

    min-width: 0 !important;

    margin: 0 !important;

    padding:
        23px
        27px
        42px;

}


/* ============================================================
   PAGE HEADER
   ============================================================ */

.placement-page-header {

    position: relative;

    width: 100%;

    min-height: 145px;

    padding:
        24px
        27px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    overflow: hidden;

    border:
        1px
        solid
        #d4c8ee;

    border-radius: 15px;

    background:

        linear-gradient(
            110deg,
            #f0e9ff 0%,
            #ffffff 52%,
            #eefaf8 100%
        );

    box-shadow:

        0
        7px
        20px
        rgba(60,50,100,.065);

}


.placement-page-header::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    bottom: 0;

    width: 5px;

    background:

        linear-gradient(
            180deg,
            #6945e6,
            #48aaa1
        );

}


.placement-page-header-copy {

    min-width: 0;

    flex: 1;

}


.placement-eyebrow {

    display: block;

    color: #6842d6;

    font-size: 8px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1.6px;

}


.placement-page-header h1 {

    margin:
        7px
        0
        6px;

    color: #122d48;

    font-size: 32px;

    line-height: 1.08;

    font-weight: 950;

    letter-spacing: -.5px;

}


.placement-page-header p {

    max-width: 1050px;

    margin: 0;

    color: #62758a;

    font-size: 12px;

    line-height: 1.6;

    font-weight: 600;

}


.placement-readonly {

    flex-shrink: 0;

    display: flex;

    align-items: center;

    gap: 8px;

    padding:
        10px
        14px;

    border:
        1px
        solid
        #b8ddd8;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #e2f8f4,
            #f2fcfb
        );

    color: #26776e;

    font-size: 9px;

    font-weight: 900;

}


/* ============================================================
   SEARCH
   ============================================================ */

.placement-search-panel {

    width: 100%;

    margin-top: 16px;

    padding:
        20px
        23px;

    border:
        1px
        solid
        #d2dfeb;

    border-radius: 14px;

    background:

        linear-gradient(
            135deg,
            #ffffff,
            #f7fbff
        );

    box-shadow:

        0
        6px
        18px
        rgba(37,52,73,.045);

}


.placement-section-heading {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 16px;

}


.placement-section-heading > div:first-child {

    min-width: 0;

}


.placement-section-heading > div:first-child span {

    display: block;

    color: #6a49d5;

    font-size: 8px;

    font-weight: 950;

    letter-spacing: 1.5px;

}


.placement-search-panel
.placement-section-heading > div:first-child span {

    color: #3571b0;

}


.placement-section-heading h2 {

    margin:
        5px
        0
        3px;

    color: #172e48;

    font-size: 20px;

    line-height: 1.15;

    font-weight: 950;

}


.placement-section-heading p {

    margin: 0;

    color: #718196;

    font-size: 10px;

    line-height: 1.45;

}


.placement-record-count {

    flex-shrink: 0;

    padding:
        7px
        11px;

    border:
        1px
        solid
        #b9e0dc;

    border-radius: 18px;

    background:
        linear-gradient(
            135deg,
            #e3f7f4,
            #f0fbfa
        );

    color: #24776f;

    font-size: 8px;

    line-height: 1;

    font-weight: 900;

    white-space: nowrap;

}


/* ============================================================
   SEARCH INPUT
   ============================================================ */

.placement-search-box {

    position: relative;

    width: 100%;

    margin-top: 15px;

}


.placement-search-box > i {

    position: absolute;

    left: 14px;

    top: 50%;

    transform: translateY(-50%);

    color: #397cc8;

    font-size: 14px;

    z-index: 2;

}


.placement-search-box input {

    width: 100%;

    height: 46px;

    padding:
        0
        40px;

    border:
        1px
        solid
        #c4d6e8;

    border-radius: 9px;

    background:

        linear-gradient(
            90deg,
            #f6faff,
            #ffffff
        );

    color: #263d54;

    font-size: 11px;

    outline: none;

}


.placement-search-box input:focus {

    background: #ffffff;

    border-color: #82aeda;

    box-shadow:
        0
        0
        0
        3px
        rgba(57,124,200,.09);

}


.placement-search-box button {

    position: absolute;

    top: 50%;

    right: 9px;

    transform:
        translateY(-50%);

    width: 27px;

    height: 27px;

    display: flex;

    align-items: center;

    justify-content: center;

    border: 0;

    border-radius: 7px;

    background: #edf2f7;

    color: #65778a;

    cursor: pointer;

}


.placement-search-box button:hover {

    background: #e8e1ff;

    color: #6440d2;

}


/* ============================================================
   STUDENT PANEL
   ============================================================ */

.placement-student-panel {

    width: 100%;

    margin-top: 16px;

    overflow: hidden;

    border:
        1px
        solid
        #d8e2e9;

    border-radius: 14px;

    background: #ffffff;

    box-shadow:

        0
        6px
        18px
        rgba(35,52,72,.045);

}


.placement-student-panel
.placement-section-heading {

    min-height: 78px;

    padding:
        17px
        23px;

    border-left:
        5px
        solid
        #159b95;

    border-bottom:
        1px
        solid
        #e6edf1;

    background:

        linear-gradient(
            90deg,
            #effaf8,
            #ffffff 55%,
            #f9f6ff
        );

}


/* ============================================================
   STUDENT ROWS
   ============================================================ */

.placement-student-row {

    position: relative;

    width: 100%;

    min-height: 81px;

    padding:
        12px
        22px;

    display: grid;

    grid-template-columns:
        minmax(280px,2.4fr)
        minmax(125px,.8fr)
        minmax(135px,.85fr)
        25px;

    align-items: center;

    gap: 18px;

    border-bottom:
        1px
        solid
        #e8edf2;

    cursor: pointer;

    transition:

        background .16s ease,
        transform .16s ease,
        box-shadow .16s ease;

}


.placement-student-row:last-child {

    border-bottom: 0;

}


.placement-student-row.student-color-0 {

    border-left:
        4px
        solid
        #6847e8;

    background:

        linear-gradient(
            90deg,
            #f7f3ff 0%,
            #ffffff 38%
        );

}


.placement-student-row.student-color-1 {

    border-left:
        4px
        solid
        #159b95;

    background:

        linear-gradient(
            90deg,
            #f0faf8 0%,
            #ffffff 38%
        );

}


.placement-student-row.student-color-2 {

    border-left:
        4px
        solid
        #397cc8;

    background:

        linear-gradient(
            90deg,
            #f1f7ff 0%,
            #ffffff 38%
        );

}


.placement-student-row.student-color-3 {

    border-left:
        4px
        solid
        #df8440;

    background:

        linear-gradient(
            90deg,
            #fff6ed 0%,
            #ffffff 38%
        );

}


.placement-student-row.student-color-4 {

    border-left:
        4px
        solid
        #d45d86;

    background:

        linear-gradient(
            90deg,
            #fff2f6 0%,
            #ffffff 38%
        );

}


.placement-student-row:hover {

    transform:
        translateX(2px);

    background:

        linear-gradient(
            90deg,
            #eee8ff,
            #f6fbff 62%,
            #ffffff
        ) !important;

    box-shadow:

        inset
        0
        1px
        0
        rgba(104,71,232,.06);

}


/* ============================================================
   STUDENT
   ============================================================ */

.placement-student-person {

    min-width: 0;

    display: flex;

    align-items: center;

}


.placement-student-avatar {

    width: 44px;

    height: 44px;

    min-width: 44px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    color: #ffffff;

    font-size: 10px;

    font-weight: 950;

}


.student-color-0
.placement-student-avatar {

    background:
        linear-gradient(
            135deg,
            #6847e8,
            #896af3
        );

}


.student-color-1
.placement-student-avatar {

    background:
        linear-gradient(
            135deg,
            #159b95,
            #45b6af
        );

}


.student-color-2
.placement-student-avatar {

    background:
        linear-gradient(
            135deg,
            #397cc8,
            #67a0db
        );

}


.student-color-3
.placement-student-avatar {

    background:
        linear-gradient(
            135deg,
            #df8440,
            #eca36b
        );

}


.student-color-4
.placement-student-avatar {

    background:
        linear-gradient(
            135deg,
            #d45d86,
            #e487a5
        );

}


.placement-student-person > div:last-child {

    min-width: 0;

    margin-left: 11px;

}


.placement-student-person strong {

    display: block;

    overflow: hidden;

    color: #19334c;

    font-size: 12px;

    line-height: 1.2;

    font-weight: 950;

    white-space: nowrap;

    text-overflow: ellipsis;

}


.placement-student-person small {

    display: block;

    margin-top: 4px;

    color: #6b7e92;

    font-size: 8px;

    font-weight: 750;

}


/* ============================================================
   READINESS
   ============================================================ */

.placement-readiness {

    min-width: 0;

    padding:
        8px
        11px;

    border:
        1px
        solid
        #dfd8f5;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #f7f3ff,
            #fcfbff
        );

}


.placement-readiness span,
.placement-risk span {

    display: block;

    margin-bottom: 5px;

    font-size: 7px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1px;

}


.placement-readiness span {

    color: #7052d7;

}


.placement-readiness strong {

    color: #5235bd;

    font-size: 15px;

    line-height: 1;

    font-weight: 950;

}


/* ============================================================
   RISK
   ============================================================ */

.placement-risk {

    min-width: 0;

    padding:
        8px
        11px;

    border:
        1px
        solid
        #dce5ef;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #f5f8fc,
            #ffffff
        );

}


.placement-risk span {

    color: #60758b;

}


.placement-risk b {

    display: inline-flex;

    align-items: center;

    padding:
        5px
        9px;

    border-radius: 17px;

    font-size: 8px;

    line-height: 1;

    font-weight: 950;

}


.risk-low {

    background:
        linear-gradient(
            135deg,
            #e3f7eb,
            #d9f1e4
        );

    color: var(--green-dark);

    border:
        1px
        solid
        #bde1ca;

}


.risk-medium {

    background:
        linear-gradient(
            135deg,
            #fff6d9,
            #ffefc2
        );

    color: var(--yellow-dark);

    border:
        1px
        solid
        #ead496;

}


.risk-high {

    background:
        linear-gradient(
            135deg,
            #ffe9e4,
            #ffddd5
        );

    color: var(--coral-dark);

    border:
        1px
        solid
        #efc2b7;

}


.risk-default {

    background: #edf2f6;

    color: #687b8d;

    border:
        1px
        solid
        #dbe3ea;

}


/* ============================================================
   ARROW
   ============================================================ */

.placement-row-arrow {

    display: flex;

    align-items: center;

    justify-content: center;

    color: #8799a9;

    font-size: 18px;

}


.placement-student-row:hover
.placement-row-arrow {

    color: #6845dc;

    transform:
        translateX(3px);

}


/* ============================================================
   EMPTY
   ============================================================ */

.placement-empty {

    padding:
        52px
        20px;

    text-align: center;

    background:
        linear-gradient(
            135deg,
            #fbfaff,
            #f8fcfb
        );

}


.placement-empty > i {

    width: 50px;

    height: 50px;

    margin: auto;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #ece5ff,
            #e1f5f1
        );

    color: #6845da;

    font-size: 18px;

}


.placement-empty h3 {

    margin:
        11px
        0
        5px;

    color: #263c53;

    font-size: 15px;

    font-weight: 950;

}


.placement-empty p {

    margin: 0;

    color: #8190a1;

    font-size: 10px;

}


/* ============================================================
   DETAIL
   ============================================================ */

.placement-detail-panel {

    width: 100%;

    margin-top: 16px;

}


/* ============================================================
   BACK
   ============================================================ */

.placement-back-button {

    margin-bottom: 12px;

    padding:
        8px
        12px;

    display: inline-flex;

    align-items: center;

    gap: 7px;

    border:
        1px
        solid
        #cec1f1;

    border-radius: 8px;

    background: #ffffff;

    color: #5635c6;

    font-size: 9px;

    font-weight: 900;

    cursor: pointer;

}


.placement-back-button:hover {

    background: #f2ecff;

    border-color: #baaae9;

    transform:
        translateX(-2px);

}


/* ============================================================
   DETAIL HEADER
   ============================================================ */

.placement-detail-header {

    width: 100%;

    min-height: 108px;

    padding:
        19px
        22px;

    display: flex;

    align-items: center;

    gap: 13px;

    border:
        1px
        solid
        #cec1ef;

    border-radius: 14px;

    background:

        linear-gradient(
            110deg,
            #f0e9ff,
            #ffffff 53%,
            #e9f9f6
        );

    box-shadow:

        0
        7px
        20px
        rgba(70,57,126,.075);

}


.placement-detail-avatar {

    width: 55px;

    height: 55px;

    min-width: 55px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #6847e8,
            #896bf3
        );

    color: #ffffff;

    font-size: 12px;

    font-weight: 950;

}


.placement-detail-person {

    min-width: 0;

    flex: 1;

}


.placement-detail-person > span {

    display: block;

    color: #6b49d3;

    font-size: 7px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1.25px;

}


.placement-detail-person h2 {

    margin:
        5px
        0;

    overflow: hidden;

    color: #142e49;

    font-size: 21px;

    line-height: 1.1;

    font-weight: 950;

    white-space: nowrap;

    text-overflow: ellipsis;

}


.placement-detail-meta {

    display: flex;

    align-items: center;

    gap: 16px;

    flex-wrap: wrap;

    color: #71849a;

    font-size: 8px;

}


.placement-detail-meta strong {

    color: #415870;

}


.placement-detail-risk {

    flex-shrink: 0;

    margin-left: auto;

    padding-left: 18px;

    border-left:
        1px
        solid
        #d2dce5;

}


.placement-detail-risk span {

    display: block;

    color: #7c8d9f;

    font-size: 7px;

    font-weight: 950;

    letter-spacing: 1px;

}


.placement-detail-risk b {

    display: inline-flex;

    margin-top: 5px;

    padding:
        6px
        10px;

    border-radius: 18px;

    font-size: 8px;

    font-weight: 950;

}


/* ============================================================
   METRICS
   ============================================================ */

.placement-metrics-grid {

    width: 100%;

    margin-top: 14px;

    display: grid;

    grid-template-columns:
        repeat(
            4,
            minmax(0,1fr)
        );

    gap: 13px;

}


.placement-metric-card {

    min-height: 110px;

    padding: 16px;

    display: flex;

    align-items: center;

    gap: 10px;

    border:
        1px
        solid;

    border-radius: 12px;

    box-shadow:
        0
        5px
        15px
        rgba(36,52,69,.045);

}


.placement-metric-card.lavender {

    background:
        linear-gradient(
            135deg,
            #e6ddff,
            #f5f0ff
        );

    border-color: #cdbdf4;

}


.placement-metric-card.teal {

    background:
        linear-gradient(
            135deg,
            #d9f5f0,
            #eefbf9
        );

    border-color: #acdcd6;

}


.placement-metric-card.coral {

    background:
        linear-gradient(
            135deg,
            #ffddd5,
            #fff2ee
        );

    border-color: #edbbb0;

}


.placement-metric-card.pink {

    background:
        linear-gradient(
            135deg,
            #f9dce7,
            #fff1f5
        );

    border-color: #e8b7c9;

}


.placement-metric-icon {

    width: 43px;

    height: 43px;

    min-width: 43px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    background: #ffffff;

    font-size: 17px;

}


.placement-metric-card.lavender
.placement-metric-icon {

    color: #6745d8;

}


.placement-metric-card.teal
.placement-metric-icon {

    color: #16877f;

}


.placement-metric-card.coral
.placement-metric-icon {

    color: #c55746;

}


.placement-metric-card.pink
.placement-metric-icon {

    color: #bd4a70;

}


.placement-metric-card > div:last-child {

    min-width: 0;

}


.placement-metric-card span {

    display: block;

    color: #718195;

    font-size: 7px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: .95px;

}


.placement-metric-card strong {

    display: block;

    margin-top: 5px;

    overflow: hidden;

    color: #17324c;

    font-size: 20px;

    line-height: 1.05;

    font-weight: 950;

    white-space: nowrap;

    text-overflow: ellipsis;

}


.placement-metric-card small {

    display: block;

    margin-top: 4px;

    color: #738499;

    font-size: 8px;

}


/* ============================================================
   DETAIL GRID
   ============================================================ */

.placement-detail-grid {

    width: 100%;

    margin-top: 14px;

    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0,1fr)
        );

    gap: 14px;

}


/* ============================================================
   INFORMATION CARD
   ============================================================ */

.placement-information-card {

    position: relative;

    width: 100%;

    padding:
        19px
        21px;

    border:
        1px
        solid
        #dce4ec;

    border-radius: 12px;

    background: #ffffff;

    box-shadow:

        0
        5px
        16px
        rgba(35,50,69,.045);

    overflow: hidden;

}


.placement-information-card::before {

    content: "";

    position: absolute;

    left: 0;

    top: 0;

    width: 100%;

    height: 4px;

    background:
        linear-gradient(
            90deg,
            #6847e8,
            #397cc8
        );

}


.placement-detail-grid
.placement-information-card:nth-child(2)::before {

    background:
        linear-gradient(
            90deg,
            #159b95,
            #397cc8
        );

}


.placement-ai-card {

    margin-top: 14px;

}


.placement-ai-card::before {

    background:
        linear-gradient(
            90deg,
            #dc6c58,
            #df8440
        );

}


.placement-card-title {

    display: flex;

    align-items: center;

    gap: 10px;

}


.placement-card-icon {

    width: 41px;

    height: 41px;

    min-width: 41px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    font-size: 16px;

}


.lavender-icon {

    background: #eee7ff;

    color: #6542d5;

}


.teal-icon {

    background: #ddf7f3;

    color: #107870;

}


.coral-icon {

    background: #ffe7e1;

    color: #b84e3c;

}


.pink-icon {

    background: #fde7ef;

    color: #b54169;

}


.placement-card-title > div:last-child {

    min-width: 0;

}


.placement-card-title span {

    display: block;

    color: #7c8d9f;

    font-size: 7px;

    line-height: 1;

    font-weight: 950;

    letter-spacing: 1.1px;

}


.placement-card-title h3 {

    margin:
        4px
        0
        0;

    color: #19324c;

    font-size: 16px;

    font-weight: 950;

}


.placement-card-body {

    margin-top: 17px;

}


.placement-card-body label {

    display: block;

    margin-bottom: 7px;

    color: #7b8d9f;

    font-size: 7px;

    font-weight: 950;

    letter-spacing: .95px;

}


.placement-card-body p {

    margin:
        8px
        0
        0;

    color: #607287;

    font-size: 10px;

    line-height: 1.65;

}


.placement-highlight {

    margin-bottom: 15px;

    padding:
        11px
        12px;

    border-radius: 8px;

    font-size: 10px;

    line-height: 1.4;

    font-weight: 900;

}


.lavender-highlight {

    background:
        linear-gradient(
            135deg,
            #efe8ff,
            #f8f5ff
        );

    border:
        1px
        solid
        #d4c6f5;

    color: #5135b7;

}


.teal-highlight {

    background:
        linear-gradient(
            135deg,
            #ddf7f3,
            #f2fcfa
        );

    border:
        1px
        solid
        #b5dfda;

    color: #0d726b;

}


/* ============================================================
   AI
   ============================================================ */

.placement-ai-content {

    margin-top: 15px;

    padding:
        14px
        16px;

    border:
        1px
        solid
        #f0d1c8;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #fff7f4,
            #fffdfb
        );

    color: #614d48;

    font-size: 10px;

    line-height: 1.7;

}


/* ============================================================
   PROFILE GRID
   ============================================================ */

.placement-profile-grid {

    width: 100%;

    margin-top: 17px;

    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0,1fr)
        );

    border:
        1px
        solid
        #e2e8ed;

    border-radius: 9px;

    overflow: hidden;

}


.placement-profile-grid > div {

    min-width: 0;

    padding:
        11px
        12px;

    background:
        linear-gradient(
            135deg,
            #fbfcff,
            #ffffff
        );

    border-bottom:
        1px
        solid
        #e7ecf1;

}


.placement-profile-grid > div:nth-child(odd) {

    border-right:
        1px
        solid
        #e7ecf1;

}


.placement-profile-grid span {

    display: block;

    margin-bottom: 5px;

    color: #7d8fa1;

    font-size: 7px;

    line-height: 1;

    font-weight: 900;

    letter-spacing: .7px;

}


.placement-profile-grid strong {

    display: block;

    overflow: hidden;

    color: #17324d;

    font-size: 10px;

    line-height: 1.3;

    font-weight: 850;

    word-break: break-word;

}


/* ============================================================
   READ ONLY
   ============================================================ */

.placement-readonly-note {

    width: 100%;

    margin-top: 14px;

    padding:
        14px
        17px;

    display: flex;

    align-items: flex-start;

    gap: 11px;

    border:
        1px
        solid
        #bddde4;

    border-left:
        4px
        solid
        #4e98ab;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #eaf8fb,
            #f5fbfd
        );

}


.placement-readonly-note > i {

    width: 35px;

    height: 35px;

    min-width: 35px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 9px;

    background: #d9eff4;

    color: #35768a;

}


.placement-readonly-note strong {

    display: block;

    color: #275e70;

    font-size: 10px;

    font-weight: 950;

}


.placement-readonly-note p {

    margin:
        4px
        0
        0;

    color: #617b87;

    font-size: 9px;

    line-height: 1.5;

}


/* ============================================================
   FOOTER
   ============================================================ */

.placement-page-footer {

    width: 100%;

    margin-top: 17px;

    padding:
        7px
        2px
        3px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    color: #8290a0;

    font-size: 8px;

    font-weight: 700;

}


/* ============================================================
   FOCUS
   ============================================================ */

.campus360-trainer-app
button:focus-visible,
.campus360-trainer-app
a:focus-visible,
.campus360-trainer-app
input:focus-visible {

    outline:
        3px
        solid
        rgba(104,71,232,.17);

    outline-offset: 2px;

}


/* ============================================================
   TABLET
   ============================================================ */

@media (max-width:1100px) {

    .campus360-trainer-app {

        --sidebar-width: 260px;

    }


    .placement-intelligence-page {

        padding:
            19px
            20px
            35px;

    }


    .placement-metrics-grid {

        grid-template-columns:
            repeat(
                2,
                minmax(0,1fr)
            );

    }


    .placement-student-row {

        grid-template-columns:
            minmax(250px,2fr)
            minmax(110px,.8fr)
            minmax(120px,.8fr)
            20px;

        gap: 12px;

    }

}


/* ============================================================
   MOBILE SIDEBAR
   ============================================================ */

@media (max-width:900px) {

    .campus360-trainer-sidebar {

        width: 280px !important;

        transform:
            translateX(-100%);

        box-shadow:

            9px
            0
            30px
            rgba(25,40,60,.18);

    }


    .campus360-trainer-app:not(.sidebar-collapsed)
    .campus360-trainer-sidebar {

        transform:
            translateX(0);

    }


    .campus360-trainer-app
    .trainer-sidebar-backdrop {

        display: none;

    }


    .campus360-trainer-app:not(.sidebar-collapsed)
    .trainer-sidebar-backdrop {

        position: fixed;

        inset: 0;

        z-index: 999998;

        display: block;

        background:
            rgba(20,34,54,.34);

    }


    .campus360-trainer-main {

        left: 0;

        width: 100vw !important;

        max-width: 100vw !important;

    }


    .placement-detail-grid {

        grid-template-columns: 1fr;

    }


    .placement-page-header {

        min-height: 125px;

    }

}


/* ============================================================
   SMALL MOBILE
   ============================================================ */

@media (max-width:650px) {

    .trainer-topbar {

        height: 64px;

        min-height: 64px;

        padding:
            0
            10px;

    }


    .trainer-hamburger {

        width: 38px;

        height: 38px;

        min-width: 38px;

    }


    .trainer-top-icon {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .trainer-top-profile-text {

        display: none;

    }


    .trainer-top-profile {

        padding-left: 4px;

    }


    .trainer-top-avatar {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .trainer-topbar-title {

        font-size: 12px;

    }


    .trainer-topbar-eyebrow {

        font-size: 8px;

    }


    .placement-intelligence-page {

        padding:
            14px
            11px
            30px;

    }


    .placement-page-header {

        flex-direction: column;

        align-items: flex-start;

        min-height: auto;

        padding: 20px;

    }


    .placement-page-header h1 {

        font-size: 25px;

    }


    .placement-page-header p {

        font-size: 10px;

    }


    .placement-section-heading {

        align-items: flex-start;

        flex-direction: column;

    }


    .placement-search-panel {

        padding: 17px;

    }


    .placement-student-panel
    .placement-section-heading {

        padding:
            16px
            18px;

    }


    .placement-student-row {

        grid-template-columns:
            1fr
            1fr;

        gap: 9px;

        padding:
            14px
            16px;

    }


    .placement-student-person {

        grid-column:
            1 / -1;

    }


    .placement-readiness,
    .placement-risk {

        width: 100%;

    }


    .placement-row-arrow {

        display: none;

    }


    .placement-metrics-grid {

        grid-template-columns: 1fr;

    }


    .placement-detail-header {

        flex-wrap: wrap;

        padding: 17px;

    }


    .placement-detail-risk {

        width: 100%;

        margin-left: 0;

        padding:
            11px
            0
            0;

        border-left: 0;

        border-top:
            1px
            solid
            #d5dee7;

    }


    .placement-profile-grid {

        grid-template-columns: 1fr;

    }


    .placement-profile-grid > div:nth-child(odd) {

        border-right: 0;

    }


    .placement-page-footer {

        flex-direction: column;

        align-items: flex-start;

        gap: 5px;

    }

}


/* ============================================================
   VERY SMALL
   ============================================================ */

@media (max-width:430px) {

    .trainer-topbar-actions {

        gap: 5px;

    }


    .trainer-page-heading {

        max-width: 145px;

    }


    .placement-page-header h1 {

        font-size: 22px;

    }


    .placement-section-heading h2 {

        font-size: 18px;

    }


    .placement-detail-person h2 {

        font-size: 18px;

    }


    .placement-detail-meta {

        flex-direction: column;

        align-items: flex-start;

        gap: 5px;

    }


    .placement-card-title h3 {

        font-size: 14px;

    }

}


/* ============================================================
   FINAL WIDTH SAFETY
   ============================================================ */

.campus360-trainer-app,
.campus360-trainer-main,
.placement-intelligence-page {

    max-width: none !important;

}


.campus360-trainer-main {

    min-width: 0 !important;

}


.placement-intelligence-page {

    overflow-x: hidden;

}
/* ============================================================
   CAMPUS360 TRAINER
   SIDEBAR ONLY - DARK PURPLE
   ============================================================ */

/* MAIN SIDEBAR */
.campus360-trainer-app .campus360-trainer-sidebar {

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border-right:
        1px solid
        #2d2157 !important;

    box-shadow:
        5px
        0
        20px
        rgba(10,7,25,.22) !important;

}


/* BRAND */
.campus360-trainer-app .trainer-brand {

    background:
        linear-gradient(
            135deg,
            #170e38,
            #1c1045
        ) !important;

    border-bottom:
        1px
        solid
        #2d2157 !important;

}


.campus360-trainer-app .trainer-brand-text strong {

    color:
        #ffffff !important;

}


.campus360-trainer-app .trainer-brand-text span {

    color:
        #b9abd8 !important;

}


/* BRAND ICON */
.campus360-trainer-app .trainer-brand-mark {

    background:
        linear-gradient(
            135deg,
            #704cf4,
            #563dd5
        ) !important;

    color:
        #ffffff !important;

    box-shadow:
        0
        8px
        19px
        rgba(91,70,230,.30) !important;

}


/* TRAINER PROFILE */
.campus360-trainer-app .trainer-profile-mini {

    background:
        linear-gradient(
            135deg,
            #211342,
            #29164f
        ) !important;

    border:
        1px
        solid
        #4b3475 !important;

}


.campus360-trainer-app .trainer-profile-mini:hover {

    background:
        linear-gradient(
            135deg,
            #29164f,
            #321a5d
        ) !important;

    border-color:
        #62478c !important;

}


.campus360-trainer-app .trainer-profile-info strong {

    color:
        #ffffff !important;

}


.campus360-trainer-app .trainer-profile-info span {

    color:
        #b9abd8 !important;

}


.campus360-trainer-app .trainer-profile-arrow {

    color:
        #a99bc7 !important;

}


/* SIDEBAR NAVIGATION */
.campus360-trainer-app .trainer-nav-label {

    color:
        #9283b6 !important;

}


.campus360-trainer-app .trainer-nav-item {

    background:
        transparent !important;

    color:
        #c4b8dc !important;

}


.campus360-trainer-app .trainer-nav-item:hover {

    background:
        rgba(124,58,237,.18) !important;

    color:
        #ffffff !important;

    transform:
        translateX(1px);

}


/* ACTIVE NAV ITEM */
.campus360-trainer-app .trainer-nav-item.active {

    background:
        linear-gradient(
            90deg,
            #7c3aed 0%,
            #8b3ff2 100%
        ) !important;

    color:
        #ffffff !important;

    border-left:
        4px
        solid
        #a78bfa !important;

    padding-left:
        7px !important;

    box-shadow:
        none !important;

}


.campus360-trainer-app .trainer-nav-item.active::before {

    display:
        none !important;

}


/* NAV ICONS */
.campus360-trainer-app .trainer-nav-icon {

    color:
        #a99ac8 !important;

}


.campus360-trainer-app .trainer-nav-item:hover
.trainer-nav-icon,

.campus360-trainer-app .trainer-nav-item.active
.trainer-nav-icon {

    color:
        #ffffff !important;

}


/* NAV COUNTS */
.campus360-trainer-app .trainer-nav-count {

    background:
        #3a2764 !important;

    color:
        #d9ceef !important;

}


.campus360-trainer-app .trainer-nav-item.active
.trainer-nav-count {

    background:
        rgba(255,255,255,.18) !important;

    color:
        #ffffff !important;

}


/* SIDEBAR SCROLLBAR */
.campus360-trainer-app .trainer-nav {

    scrollbar-width:
        none;

    -ms-overflow-style:
        none;

}


.campus360-trainer-app .trainer-nav::-webkit-scrollbar {

    width:
        0;

    height:
        0;

}


/* MOBILE SIDEBAR */
@media (max-width:900px) {

    .campus360-trainer-app .campus360-trainer-sidebar {

        background:
            linear-gradient(
                180deg,
                #130d2f 0%,
                #160d38 48%,
                #100a29 100%
            ) !important;

        border-right:
            1px
            solid
            #2d2157 !important;

        box-shadow:
            9px
            0
            30px
            rgba(10,7,25,.32) !important;

    }

}


/* FINAL SAFETY OVERRIDE - SIDEBAR ONLY */
.campus360-trainer-app
.campus360-trainer-sidebar {

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

}

sp_widget.script:
(function() {


  /* ============================================================
     INITIAL DATA
     ============================================================ */

  data.loaded = true;

  data.records = [];

  data.trainer = {

    id: '',
    name: 'Trainer',
    initials: 'TR'

  };


  /* ============================================================
     TRAINER
     ============================================================ */

  var trainerId =
    $sp.getParameter('trainer') ||
    '';


  if (
    input &&
    input.trainer
  ) {

    trainerId =
      input.trainer;

  }


  if (trainerId) {

    var trainerGR =
      new GlideRecord(
        'x_snc_campus360_trainer_master'
      );


    if (
      trainerGR.isValid()
    ) {

      trainerGR.addQuery(
        'trainer_id',
        trainerId
      );

      trainerGR.setLimit(1);

      trainerGR.query();


      if (
        trainerGR.next()
      ) {

        data.trainer.id =
          trainerGR.getValue(
            'trainer_id'
          ) ||
          trainerId;


        data.trainer.name =
          trainerGR.getValue(
            'trainer_name'
          ) ||
          'Trainer';

      }

    }

  }


  function getInitials(name) {

    if (!name) {
      return 'TR';
    }


    var parts =
      name
        .toString()
        .trim()
        .split(/\s+/);


    if (
      parts.length === 1
    ) {

      return parts[0]
        .substring(0, 2)
        .toUpperCase();

    }


    return (
      parts[0].charAt(0) +
      parts[
        parts.length - 1
      ].charAt(0)
    ).toUpperCase();

  }


  data.trainer.initials =
    getInitials(
      data.trainer.name
    );


  /* ============================================================
     STUDENT IDS CONNECTED TO TRAINER
     ============================================================ */

  var trainerStudentIds = {};


  /*
   * Training Enrollment is used to determine
   * which students belong to this trainer.
   */

  var enrollmentGR =
    new GlideRecord(
      'x_snc_campus360_training_enrollment'
    );


  if (
    enrollmentGR.isValid()
  ) {

    if (trainerId) {

      var trainerSysId = '';


      var trainerLookup =
        new GlideRecord(
          'x_snc_campus360_trainer_master'
        );


      if (
        trainerLookup.isValid()
      ) {

        trainerLookup.addQuery(
          'trainer_id',
          trainerId
        );

        trainerLookup.setLimit(1);

        trainerLookup.query();


        if (
          trainerLookup.next()
        ) {

          trainerSysId =
            trainerLookup.getUniqueValue();

        }

      }


      if (trainerSysId) {

        enrollmentGR.addQuery(
          'trainer',
          trainerSysId
        );

      }

    }


    enrollmentGR.query();


    while (
      enrollmentGR.next()
    ) {

      var enrolledStudent =
        enrollmentGR.getValue(
          'student'
        );


      if (enrolledStudent) {

        trainerStudentIds[
          enrolledStudent
        ] = true;

      }

    }

  }


  /* ============================================================
     PLACEMENT INTELLIGENCE
     ============================================================ */

  var intelligenceGR =
    new GlideRecord(
      'x_snc_campus360_placement_intelligence'
    );


  intelligenceGR.orderByDesc(
    'last_updated'
  );


  intelligenceGR.query();


  while (
    intelligenceGR.next()
  ) {


    var studentSysId =
      intelligenceGR.getValue(
        'student'
      );


    /*
     * If trainer/student relationships exist,
     * only show the trainer's students.
     *
     * If no enrollment relationship exists yet,
     * keep the intelligence visible so the page
     * does not incorrectly appear empty.
     */

    if (
      Object.keys(
        trainerStudentIds
      ).length > 0 &&
      !trainerStudentIds[
        studentSysId
      ]
    ) {

      continue;

    }


    /* ==========================================================
       STUDENT
       ========================================================== */

    var studentGR =
      new GlideRecord(
        'x_snc_campus360_student_master'
      );


    var studentName =
      'Student';

    var studentId =
      '';

    var email =
      '';

    var phone =
      '';

    var branch =
      '';

    var degree =
      '';

    var batch =
      '';

    var cgpa =
      '';

    var placementStatus =
      '';

    var profileStatus =
      '';


    if (
      studentSysId &&
      studentGR.get(
        studentSysId
      )
    ) {

      studentName =
        studentGR.getValue(
          'student_name'
        ) ||
        studentGR.getDisplayValue();


      studentId =
        studentGR.getValue(
          'student_id'
        ) ||
        '';


      email =
        studentGR.getValue(
          'email'
        ) ||
        '';


      phone =
        studentGR.getValue(
          'phone_number'
        ) ||
        '';


      branch =
        studentGR.getDisplayValue(
          'branch'
        ) ||
        '';


      degree =
        studentGR.getDisplayValue(
          'degree'
        ) ||
        '';


      batch =
        studentGR.getValue(
          'batch'
        ) ||
        '';


      cgpa =
        studentGR.getValue(
          'cgpa'
        ) ||
        '';


      placementStatus =
        studentGR.getDisplayValue(
          'placement_status'
        ) ||
        '';


      profileStatus =
        studentGR.getDisplayValue(
          'profile_status'
        ) ||
        '';

    }


    /* ==========================================================
       INTELLIGENCE
       ========================================================== */

    var readiness =
      parseInt(
        intelligenceGR.getValue(
          'readiness_score'
        ),
        10
      ) || 0;


    var participation =
      parseInt(
        intelligenceGR.getValue(
          'participation_score'
        ),
        10
      ) || 0;


    var missedOpportunities =
      parseInt(
        intelligenceGR.getValue(
          'missed_opportunities'
        ),
        10
      ) || 0;


    var risk =
      intelligenceGR.getDisplayValue(
        'risk_level'
      ) ||
      'Not Available';


    var primarySkillGap =
      intelligenceGR.getDisplayValue(
        'primary_skill_gap'
      ) ||
      '';


    var skillGapSummary =
      intelligenceGR.getValue(
        'skill_gap_summary'
      ) ||
      '';


    var recommendedAction =
      intelligenceGR.getValue(
        'recommended_action'
      ) ||
      '';


    var bottleneckStage =
      intelligenceGR.getDisplayValue(
        'bottleneck_stage'
      ) ||
      '';


    var aiInsight =
      intelligenceGR.getValue(
        'ai_insight'
      ) ||
      '';


    var intelligenceId =
      intelligenceGR.getValue(
        'intelligence_id'
      ) ||
      '';


    /* ==========================================================
       RECORD
       ========================================================== */

    data.records.push({

      sys_id:
        intelligenceGR.getUniqueValue(),

      intelligence_id:
        intelligenceId,

      student_id:
        studentId,

      name:
        studentName,

      initials:
        getInitials(
          studentName
        ),

      email:
        email,

      phone_number:
        phone,

      branch:
        branch,

      degree:
        degree,

      batch:
        batch,

      cgpa:
        cgpa,

      placement_status:
        placementStatus,

      profile_status:
        profileStatus,

      readiness:
        readiness,

      participation:
        participation,

      risk:
        risk,

      primary_skill_gap:
        primarySkillGap,

      skill_gap_summary:
        skillGapSummary,

      recommended_action:
        recommendedAction,

      bottleneck_stage:
        bottleneckStage,

      ai_insight:
        aiInsight,

      missed_opportunities:
        missedOpportunities

    });

  }


  /* ============================================================
     FALLBACK TEST DATA HANDLING
     ============================================================ */

  if (
    data.records.length === 0
  ) {

    /*
     * Do not create fake placement intelligence.
     * The page will correctly show the empty state
     * until actual records exist for the trainer's students.
     */

    data.records = [];

  }


})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
